"""Typed contracts between the layers.

These are the only shapes that cross a layer boundary. Every one is validated
*at the boundary*, so a malformed plan never reaches the translator and a model
that returns an out-of-range value is re-asked rather than silently coerced.

The validators are deliberately verbose: their messages are fed straight back to
the agent as the repair prompt, so "room R-04 target_area_m2=0.0 must be > 0" is
worth more than a stack trace.

No LLM ever sees a coordinate here. `ArchitectPlan` carries areas, categories and
adjacencies; turning those into metres is `recognition.translate`'s job, and that
separation is what stops a model inventing a plausible-looking wall position.
"""
from __future__ import annotations

import json
from dataclasses import asdict, dataclass, field
from pathlib import Path
from typing import Any

SCHEMA_BRIEF = "designbrief/v1"
SCHEMA_PLAN = "architectplan/v1"

# Categories the downstream model/rules already understand (recognition.model).
CATEGORIES = (
    "bedroom", "living", "kitchen", "bathroom", "office", "meeting",
    "lab", "hall", "utility", "stair", "roof", "other",
)
HABITABLE = ("bedroom", "living", "kitchen", "office")
ACCESS_TIERS = ("none", "din18040_2", "din18040_2_R")


class ContractError(ValueError):
    """Raised when an artifact crossing a layer boundary is malformed.

    The message is the repair instruction. Keep it specific and actionable.
    """


def _req(d: dict, key: str, kind: type, where: str) -> Any:
    if key not in d:
        raise ContractError(f"{where}: missing required field '{key}'")
    v = d[key]
    if not isinstance(v, kind):
        raise ContractError(
            f"{where}: '{key}' must be {kind.__name__}, got {type(v).__name__} ({v!r})"
        )
    return v


# --------------------------------------------------------------------------
# DesignBrief — SoT-1, written by L1 (the interview)
# --------------------------------------------------------------------------

@dataclass
class RoomRequest:
    category: str
    count: int = 1
    min_area_m2: float | None = None
    label: str | None = None

    def validate(self, where: str) -> None:
        if self.category not in CATEGORIES:
            raise ContractError(
                f"{where}: category '{self.category}' is not one of {list(CATEGORIES)}"
            )
        if self.count < 1:
            raise ContractError(f"{where}: count must be >= 1, got {self.count}")
        if self.min_area_m2 is not None and self.min_area_m2 <= 0:
            raise ContractError(f"{where}: min_area_m2 must be > 0, got {self.min_area_m2}")


@dataclass
class Assumption:
    """A value the system inferred rather than being told.

    Every inferred value must appear here. There is no third category: a value is
    either confirmed by the client or declared as an assumption. This is the
    honesty surface -- the silent default is the failure mode we are designing out.
    """
    slot: str
    value: Any
    basis: str
    confidence: str = "medium"
    confirmed: bool = False


@dataclass
class DesignBrief:
    project: str
    bundesland: str = "BY"
    building_class: str = "detached_house"
    plot_width_m: float = 18.0
    plot_depth_m: float = 24.0
    dwelling_count: int = 1
    storey_count: int = 1
    storey_height_m: float = 2.50
    occupants: int = 4
    rooms: list[RoomRequest] = field(default_factory=list)
    accessibility_tier: str = "none"
    assumptions: list[Assumption] = field(default_factory=list)
    notes: str = ""
    schema: str = SCHEMA_BRIEF

    # -- derived -----------------------------------------------------------

    def resolve_accessibility(self) -> None:
        """BayBO Art. 48 (1): above two dwellings, one storey must be barrier-free.

        Derived, never asked directly -- and recorded as an assumption so the
        client can see the rule that forced it.
        """
        if self.dwelling_count > 2 and self.accessibility_tier == "none":
            self.accessibility_tier = "din18040_2"
            self.assumptions.append(Assumption(
                slot="accessibility_tier",
                value="din18040_2",
                basis="BayBO Art. 48 (1): more than 2 dwellings requires one storey barrier-free",
                confidence="high",
            ))

    def validate(self) -> DesignBrief:
        w = "DesignBrief"
        if not self.project.strip():
            raise ContractError(f"{w}: 'project' must not be empty")
        if self.accessibility_tier not in ACCESS_TIERS:
            raise ContractError(
                f"{w}: accessibility_tier '{self.accessibility_tier}' not in {list(ACCESS_TIERS)}"
            )
        if self.dwelling_count < 1:
            raise ContractError(f"{w}: dwelling_count must be >= 1, got {self.dwelling_count}")
        if self.storey_count != 1:
            # v1 constraint, stated loudly rather than failing mysteriously later.
            raise ContractError(
                f"{w}: storey_count must be 1 in v1 (multi-storey is not implemented); got {self.storey_count}"
            )
        if self.storey_height_m < 2.40:
            raise ContractError(
                f"{w}: storey_height_m {self.storey_height_m} is below the BayBO Art. 45 (1) "
                "minimum clear height of 2.40 m"
            )
        if not self.rooms:
            raise ContractError(f"{w}: at least one room is required")
        for i, r in enumerate(self.rooms):
            r.validate(f"{w}.rooms[{i}]")
        if self.plot_width_m <= 0 or self.plot_depth_m <= 0:
            raise ContractError(f"{w}: plot dimensions must be > 0")
        return self

    # -- io ----------------------------------------------------------------

    def to_dict(self) -> dict:
        return asdict(self)

    @classmethod
    def from_dict(cls, d: dict) -> DesignBrief:
        rooms = [RoomRequest(**r) for r in d.get("rooms", [])]
        assumptions = [Assumption(**a) for a in d.get("assumptions", [])]
        known = {f for f in cls.__dataclass_fields__}
        kw = {k: v for k, v in d.items() if k in known and k not in ("rooms", "assumptions")}
        return cls(rooms=rooms, assumptions=assumptions, **kw)

    def write(self, path: str | Path) -> Path:
        p = Path(path)
        p.parent.mkdir(parents=True, exist_ok=True)
        p.write_text(json.dumps(self.to_dict(), indent=2, ensure_ascii=False), encoding="utf-8")
        return p

    @classmethod
    def read(cls, path: str | Path) -> DesignBrief:
        return cls.from_dict(json.loads(Path(path).read_text(encoding="utf-8")))


# --------------------------------------------------------------------------
# ArchitectPlan -- written by L2 (the architect), read by L3 (the translator)
# --------------------------------------------------------------------------

@dataclass
class RoomSpec:
    id: str
    category: str
    label: str
    target_area_m2: float
    exterior_wall: bool = True

    def validate(self, where: str) -> None:
        if not self.id.strip():
            raise ContractError(f"{where}: room 'id' must not be empty")
        if self.category not in CATEGORIES:
            raise ContractError(
                f"{where}: category '{self.category}' is not one of {list(CATEGORIES)}"
            )
        if self.target_area_m2 <= 0:
            raise ContractError(
                f"{where}: room {self.id} target_area_m2 must be > 0, got {self.target_area_m2}"
            )


@dataclass
class Adjacency:
    a: str
    b: str
    via: str = "door"   # door | open

    def validate(self, where: str, ids: set[str]) -> None:
        for side in (self.a, self.b):
            if side not in ids:
                raise ContractError(f"{where}: adjacency references unknown room '{side}'")
        if self.a == self.b:
            raise ContractError(f"{where}: room '{self.a}' cannot be adjacent to itself")
        if self.via not in ("door", "open"):
            raise ContractError(f"{where}: 'via' must be 'door' or 'open', got '{self.via}'")


@dataclass
class Envelope:
    width_m: float
    depth_m: float
    external_wall_m: float = 0.30
    internal_wall_m: float = 0.15

    @property
    def area_m2(self) -> float:
        return self.width_m * self.depth_m

    def validate(self, where: str) -> None:
        if self.width_m <= 0 or self.depth_m <= 0:
            raise ContractError(f"{where}: envelope dimensions must be > 0")
        if self.external_wall_m <= 0 or self.internal_wall_m <= 0:
            raise ContractError(f"{where}: wall thicknesses must be > 0")


@dataclass
class ArchitectPlan:
    """Relationships and areas. Deliberately no coordinates -- see module docstring."""
    project: str
    envelope: Envelope
    rooms: list[RoomSpec]
    adjacency: list[Adjacency] = field(default_factory=list)
    storey_name: str = "Erdgeschoss"
    storey_height_m: float = 2.50
    circulation_id: str | None = None
    glazing_ratio: float = 0.125          # BayBO Art. 45 (2) = 1/8
    accessibility_tier: str = "none"
    rationale: str = ""
    todo_agent: list[str] = field(default_factory=list)
    schema: str = SCHEMA_PLAN

    # -- validation --------------------------------------------------------

    def validate(self) -> ArchitectPlan:
        w = "ArchitectPlan"
        self.envelope.validate(f"{w}.envelope")
        if not self.rooms:
            raise ContractError(f"{w}: at least one room is required")

        ids: set[str] = set()
        for i, r in enumerate(self.rooms):
            r.validate(f"{w}.rooms[{i}]")
            if r.id in ids:
                raise ContractError(f"{w}: duplicate room id '{r.id}'")
            ids.add(r.id)

        for i, a in enumerate(self.adjacency):
            a.validate(f"{w}.adjacency[{i}]", ids)

        # Areas must physically fit, allowing for walls. Checked *before* geometry
        # exists, so an impossible plan costs one cheap call instead of a full
        # geometry round-trip.
        wanted = sum(r.target_area_m2 for r in self.rooms)
        usable = self.usable_area_m2()
        if wanted > usable + 1e-6:
            raise ContractError(
                f"{w}: rooms need {wanted:.1f} m2 but the envelope only offers "
                f"{usable:.1f} m2 of usable floor after wall thickness. "
                f"Reduce room areas or enlarge the envelope "
                f"({self.envelope.width_m} x {self.envelope.depth_m} m)."
            )

        if self.circulation_id is not None and self.circulation_id not in ids:
            raise ContractError(f"{w}: circulation_id '{self.circulation_id}' is not a known room")

        if not 0 < self.glazing_ratio < 1:
            raise ContractError(f"{w}: glazing_ratio must be between 0 and 1, got {self.glazing_ratio}")

        if len(self.rooms) > 1 and self.adjacency:
            self._assert_connected(ids)
        return self

    def _assert_connected(self, ids: set[str]) -> None:
        """Every room must be reachable. A disconnected plan is a bug, not a style."""
        graph: dict[str, set[str]] = {i: set() for i in ids}
        for a in self.adjacency:
            graph[a.a].add(a.b)
            graph[a.b].add(a.a)
        start = next(iter(ids))
        seen, stack = {start}, [start]
        while stack:
            for nxt in graph[stack.pop()]:
                if nxt not in seen:
                    seen.add(nxt)
                    stack.append(nxt)
        if seen != ids:
            missing = sorted(ids - seen)
            raise ContractError(
                f"ArchitectPlan: rooms {missing} are not reachable from the rest of the plan. "
                "Add an adjacency connecting them (usually to the circulation room)."
            )

    # -- derived -----------------------------------------------------------

    def usable_area_m2(self) -> float:
        """Envelope area minus the external wall band and an allowance for partitions."""
        e = self.envelope
        inner_w = e.width_m - e.external_wall_m
        inner_d = e.depth_m - e.external_wall_m
        gross = max(inner_w, 0.0) * max(inner_d, 0.0)
        # Partition allowance: roughly one internal wall per room boundary.
        partitions = max(len(self.rooms) - 1, 0) * e.internal_wall_m * max(inner_w, inner_d)
        return max(gross - partitions, 0.0)

    def room(self, room_id: str) -> RoomSpec:
        for r in self.rooms:
            if r.id == room_id:
                return r
        raise ContractError(f"ArchitectPlan: no room with id '{room_id}'")

    # -- io ----------------------------------------------------------------

    def to_dict(self) -> dict:
        return asdict(self)

    @classmethod
    def from_dict(cls, d: dict) -> ArchitectPlan:
        env = Envelope(**d["envelope"]) if isinstance(d.get("envelope"), dict) else d["envelope"]
        rooms = [RoomSpec(**r) for r in d.get("rooms", [])]
        adj = [Adjacency(**a) for a in d.get("adjacency", [])]
        known = {f for f in cls.__dataclass_fields__}
        kw = {k: v for k, v in d.items()
              if k in known and k not in ("envelope", "rooms", "adjacency")}
        return cls(envelope=env, rooms=rooms, adjacency=adj, **kw)

    def write(self, path: str | Path) -> Path:
        p = Path(path)
        p.parent.mkdir(parents=True, exist_ok=True)
        p.write_text(json.dumps(self.to_dict(), indent=2, ensure_ascii=False), encoding="utf-8")
        return p

    @classmethod
    def read(cls, path: str | Path) -> ArchitectPlan:
        return cls.from_dict(json.loads(Path(path).read_text(encoding="utf-8")))


def load_plan(raw: str | dict) -> ArchitectPlan:
    """Parse and validate whatever an agent returned. Never trust it unchecked."""
    if isinstance(raw, str):
        try:
            raw = json.loads(raw)
        except json.JSONDecodeError as e:
            raise ContractError(f"ArchitectPlan: response is not valid JSON ({e})") from e
    if not isinstance(raw, dict):
        raise ContractError(f"ArchitectPlan: expected a JSON object, got {type(raw).__name__}")
    return ArchitectPlan.from_dict(raw).validate()

"""Devin API v1 client and parallel session fan-out.

The org's key is a legacy `apk_user_` key: the v3 endpoints return 403 for it and
v1 works, so v1 is what this speaks. The version lives in one constant.

Two v1 quirks that will bite anyone reading this later:

* A finished session reports ``status_enum: "blocked"`` *with* ``structured_output``
  populated. It never reports "finished". Treating "blocked" as failure will hang
  the orchestrator forever.
* Attachment upload returns a bare text URL, which goes into the prompt as an
  ``ATTACHMENT:"<url>"`` line rather than a JSON field.

Nothing in this module decides whether work is good. It starts sessions, polls
them, and reports what they produced; `recognition.score` is the only judge.
"""
from __future__ import annotations

import json
import os
import time
from dataclasses import dataclass, field
from pathlib import Path
from typing import Any, Callable

import httpx

DEVIN_API = "https://api.devin.ai/v1"

# A session is done when it is blocked *and* has handed back structured output.
TERMINAL = ("blocked", "finished", "expired", "stopped")


class DevinError(RuntimeError):
    pass


def extract_json(text: str) -> dict | None:
    """Pull the first JSON object out of an agent message.

    Handles a ```json fence and a bare object, and tolerates prose either side.
    Returns None rather than raising: a message with no JSON in it is a normal
    outcome (the session asked a question), not an error.
    """
    if not text:
        return None
    fence = text.find("```")
    if fence != -1:
        rest = text[fence + 3:]
        if rest[:4].lower().startswith("json"):
            rest = rest[4:]
        end = rest.find("```")
        candidate = rest[:end] if end != -1 else rest
        try:
            v = json.loads(candidate.strip())
            if isinstance(v, dict):
                return v
        except json.JSONDecodeError:
            pass
    start = text.find("{")
    while start != -1:
        depth, in_str, esc = 0, False, False
        for i in range(start, len(text)):
            ch = text[i]
            if in_str:
                if esc:
                    esc = False
                elif ch == "\\":
                    esc = True
                elif ch == '"':
                    in_str = False
                continue
            if ch == '"':
                in_str = True
            elif ch == "{":
                depth += 1
            elif ch == "}":
                depth -= 1
                if depth == 0:
                    try:
                        v = json.loads(text[start:i + 1])
                        if isinstance(v, dict):
                            return v
                    except json.JSONDecodeError:
                        break
        start = text.find("{", start + 1)
    return None


@dataclass
class SessionResult:
    """What one Devin session produced. No judgement attached."""
    session_id: str
    status: str = "unknown"
    structured_output: dict | None = None
    pull_request_url: str = ""
    branch: str = ""
    last_message: str = ""
    error: str = ""

    @property
    def done(self) -> bool:
        if self.error:
            return True
        if self.status in ("expired", "stopped", "finished"):
            return True
        # The important one: blocked + structured output means success in v1.
        return self.status == "blocked" and self.structured_output is not None

    @property
    def produced_output(self) -> bool:
        return bool(self.structured_output)


class DevinClient:
    """Thin, synchronous v1 client. One method per endpoint we actually use."""

    def __init__(self, api_key: str | None = None, *, base: str = DEVIN_API,
                 timeout: float = 60.0) -> None:
        key = api_key or os.environ.get("DEVIN_API_KEY", "")
        if not key:
            raise DevinError(
                "No Devin API key. Set DEVIN_API_KEY in the environment or a local .env "
                "(never commit it), or run the pipeline with --engine local."
            )
        self._key = key
        self.base = base.rstrip("/")
        self._http = httpx.Client(
            timeout=timeout,
            headers={"Authorization": f"Bearer {key}", "Content-Type": "application/json"},
        )

    # -- endpoints ---------------------------------------------------------

    def create_session(self, prompt: str, *, title: str | None = None,
                       playbook_id: str | None = None, tags: list[str] | None = None,
                       max_acu: int | None = None,
                       structured_output: dict | str | None = None) -> str:
        body: dict[str, Any] = {"prompt": prompt}
        if title:
            body["title"] = title[:120]
        if playbook_id:
            body["playbook_id"] = playbook_id
        if tags:
            body["tags"] = tags
        if max_acu is not None:
            body["max_acu_limit"] = max_acu
        if structured_output is not None:
            body["structured_output"] = (
                structured_output if isinstance(structured_output, str)
                else json.dumps(structured_output)
            )
        r = self._http.post(f"{self.base}/sessions", json=body)
        if r.status_code >= 400:
            raise DevinError(f"create_session failed ({r.status_code}): {r.text[:400]}")
        sid = r.json().get("session_id")
        if not sid:
            raise DevinError(f"create_session returned no session_id: {r.text[:300]}")
        return sid

    def get_session(self, session_id: str) -> dict:
        r = self._http.get(f"{self.base}/session/{session_id}")
        if r.status_code >= 400:
            raise DevinError(f"get_session failed ({r.status_code}): {r.text[:300]}")
        return r.json()

    def send_message(self, session_id: str, text: str) -> None:
        r = self._http.post(f"{self.base}/session/{session_id}/message",
                            json={"message": text})
        if r.status_code >= 400:
            raise DevinError(f"send_message failed ({r.status_code}): {r.text[:300]}")

    def upload_attachment(self, path: str | Path) -> str:
        """Returns a bare URL string, which belongs in the prompt as ATTACHMENT:"…"."""
        p = Path(path)
        with p.open("rb") as fh:
            r = httpx.post(f"{self.base}/attachments",
                           headers={"Authorization": f"Bearer {self._key}"},
                           files={"file": (p.name, fh)}, timeout=120.0)
        if r.status_code >= 400:
            raise DevinError(f"upload_attachment failed ({r.status_code}): {r.text[:300]}")
        return r.text.strip().strip('"')

    def close(self) -> None:
        self._http.close()

    # -- polling -----------------------------------------------------------

    def snapshot(self, session_id: str) -> SessionResult:
        try:
            s = self.get_session(session_id)
        except DevinError as e:
            return SessionResult(session_id, status="error", error=str(e))
        so = s.get("structured_output")
        if isinstance(so, str):
            try:
                so = json.loads(so)
            except json.JSONDecodeError:
                so = {"raw": so}
        pr = s.get("pull_request") or {}
        msgs = s.get("messages") or []
        last = ""
        last_full = ""
        for m in reversed(msgs):
            if isinstance(m, dict) and m.get("message") and m.get("type") != "initial_user_message":
                last_full = str(m["message"])
                last = last_full[:800]
                break

        # Observed in v1: a session can answer correctly in a normal message and
        # never populate structured_output at all. Waiting on that field alone
        # hangs the run until timeout, so recover the payload from the message.
        if not isinstance(so, dict) and last_full:
            so = extract_json(last_full)
        return SessionResult(
            session_id=session_id,
            status=str(s.get("status_enum") or s.get("status") or "unknown"),
            structured_output=so if isinstance(so, dict) else None,
            pull_request_url=str(pr.get("url", "") or ""),
            branch=str(s.get("branch_name", "") or ""),
            last_message=last,
        )


# --------------------------------------------------------------------------
# Fan-out
# --------------------------------------------------------------------------

@dataclass
class SessionSpec:
    """One candidate to explore. `strategy` is what makes the siblings differ."""
    name: str
    strategy: str
    prompt: str
    tags: list[str] = field(default_factory=list)
    max_acu: int | None = None


def fan_out(client: DevinClient, specs: list[SessionSpec], *,
            structured_output: dict | str | None = None,
            playbook_id: str | None = None) -> dict[str, str]:
    """Start every session up front so they explore concurrently.

    Returns {spec.name: session_id}. A session that fails to start is recorded as
    an empty id rather than aborting its siblings -- one dead candidate must not
    take the run down.
    """
    ids: dict[str, str] = {}
    for spec in specs:
        try:
            ids[spec.name] = client.create_session(
                spec.prompt, title=f"Recognition · {spec.name}",
                playbook_id=playbook_id, tags=spec.tags or ["recognition", "autopilot"],
                max_acu=spec.max_acu, structured_output=structured_output,
            )
        except DevinError as e:
            ids[spec.name] = ""
            print(f"  ! session '{spec.name}' failed to start: {e}")
    return ids


def wait_all(client: DevinClient, ids: dict[str, str], *, timeout_s: float = 1800,
             interval_s: float = 15.0,
             on_update: Callable[[str, SessionResult], None] | None = None,
             ) -> dict[str, SessionResult]:
    """Poll every live session until each is done or the whole run times out.

    Timing out is a normal outcome, not an exception: the orchestrator scores
    whatever finished. A slow sibling must never block a good answer.
    """
    results: dict[str, SessionResult] = {
        name: SessionResult(sid, status="error" if not sid else "starting",
                            error="" if sid else "session did not start")
        for name, sid in ids.items()
    }
    deadline = time.monotonic() + timeout_s
    while time.monotonic() < deadline:
        pending = [n for n, r in results.items() if not r.done]
        if not pending:
            break
        for name in pending:
            snap = client.snapshot(results[name].session_id)
            if snap.status != results[name].status or snap.done:
                if on_update:
                    on_update(name, snap)
            results[name] = snap
        if all(r.done for r in results.values()):
            break
        time.sleep(interval_s)
    for name, r in results.items():
        if not r.done and not r.error:
            r.error = f"timed out after {timeout_s:.0f}s in status '{r.status}'"
    return results


# The shape every builder session must hand back. Declared once, sent to Devin as
# the structured-output schema so the reply is machine-readable by construction.
PLAN_OUTPUT_SCHEMA = {
    "type": "object",
    "properties": {
        "branch": {"type": "string", "description": "branch the work was pushed to"},
        "plan_path": {"type": "string", "description": "path to the ArchitectPlan JSON in the repo"},
        "verdict": {"type": "string", "enum": ["PASS", "FAIL"],
                    "description": "result of `recognition verify` that the session ran itself"},
        "blocking_failures": {"type": "integer"},
        "notes": {"type": "string", "description": "what strategy was taken and why"},
    },
    "required": ["verdict", "notes"],
}

"""Compliance rules engine.

Rules are declared in YAML (thresholds = data) and implemented here as small
functions (logic = code). Each rule returns one Result per element it checks,
pass or fail, so the report can show coverage as well as failures.

This is the verifier of the harness: a failing rule is the signal Devin uses
to know its work is not done.
"""
from __future__ import annotations

import json
from dataclasses import asdict, dataclass
from pathlib import Path
from typing import Callable

import yaml

from .model import Model, Space, _rect_dims

DEFAULT_RULESET = Path(__file__).resolve().parent.parent / "rules" / "residential.yaml"
HABITABLE = ("bedroom", "living", "kitchen", "bathroom", "office")


@dataclass
class Result:
    rule_id: str
    severity: str
    title: str
    element_tag: str
    element_name: str
    storey: str
    value: float | None
    limit: float | None
    passed: bool
    message: str


@dataclass
class Report:
    ruleset: str
    version: str
    model: str
    results: list[Result]

    @property
    def failures(self) -> list[Result]:
        return [r for r in self.results if not r.passed]

    @property
    def errors(self) -> list[Result]:
        return [r for r in self.failures if r.severity == "error"]

    @property
    def warnings(self) -> list[Result]:
        return [r for r in self.failures if r.severity == "warning"]

    def summary(self) -> dict:
        by_rule: dict[str, dict] = {}
        for r in self.results:
            d = by_rule.setdefault(r.rule_id, {"checked": 0, "failed": 0, "severity": r.severity, "title": r.title})
            d["checked"] += 1
            d["failed"] += 0 if r.passed else 1
        return {
            "checks": len(self.results), "passed": len(self.results) - len(self.failures),
            "errors": len(self.errors), "warnings": len(self.warnings), "by_rule": by_rule,
        }


RuleFn = Callable[[Model, dict, dict], list[Result]]
REGISTRY: dict[str, RuleFn] = {}


def rule(rule_id: str):
    def deco(fn: RuleFn):
        REGISTRY[rule_id] = fn
        return fn
    return deco


def _res(spec: dict, el, value, limit, passed, msg) -> Result:
    return Result(spec["id"], spec["severity"], spec["title"], el.tag, getattr(el, "label", el.name),
                  el.storey, None if value is None else round(value, 3), limit, passed, msg)


@rule("ROOM-MIN-AREA")
def room_min_area(model: Model, params: dict, spec: dict) -> list[Result]:
    out = []
    for s in model.spaces:
        lim = params.get(s.category)
        if lim is None:
            continue
        ok = s.area >= lim
        out.append(_res(spec, s, s.area, lim, ok,
                        f"{s.label}: {s.area:.2f} m² {'≥' if ok else '<'} {lim} m² required for {s.category}"))
    return out


@rule("ROOM-MIN-WIDTH")
def room_min_width(model: Model, params: dict, spec: dict) -> list[Result]:
    out = []
    for s in model.spaces:
        lim = params.get(s.category)
        if lim is None:
            continue
        width, _ = _rect_dims(s.footprint)
        ok = width >= lim
        out.append(_res(spec, s, width, lim, ok,
                        f"{s.label}: clear width {width:.2f} m {'≥' if ok else '<'} {lim} m for {s.category}"))
    return out


@rule("DOOR-MIN-WIDTH")
def door_min_width(model: Model, params: dict, spec: dict) -> list[Result]:
    out = []
    for d in model.doors:
        lim = params["external"] if d.is_external else params["interior"]
        ok = d.width + 1e-6 >= lim
        out.append(_res(spec, d, d.width, lim, ok,
                        f"{d.tag} {d.name}: leaf width {d.width:.3f} m {'≥' if ok else '<'} {lim} m "
                        f"({'external' if d.is_external else 'interior'})"))
    return out


@rule("DOOR-MIN-HEIGHT")
def door_min_height(model: Model, params: dict, spec: dict) -> list[Result]:
    lim = params["min"]
    return [_res(spec, d, d.height, lim, d.height + 1e-6 >= lim,
                 f"{d.tag} {d.name}: height {d.height:.3f} m {'≥' if d.height + 1e-6 >= lim else '<'} {lim} m")
            for d in model.doors]


@rule("ROOM-DAYLIGHT")
def room_daylight(model: Model, params: dict, spec: dict) -> list[Result]:
    out = []
    applies = set(params.get("applies_to", HABITABLE))
    # assign each window to the single space it serves most
    glazing: dict[str, float] = {}
    for w in model.windows:
        rooms = model.spaces_touching(w)
        if rooms:
            glazing[rooms[0].guid] = glazing.get(rooms[0].guid, 0.0) + w.width * w.height
    for s in model.spaces:
        if s.category not in applies:
            continue
        ratio = glazing.get(s.guid, 0.0) / s.area if s.area else 0.0
        ok = ratio >= params["min_ratio"]
        out.append(_res(spec, s, ratio, params["min_ratio"], ok,
                        f"{s.label}: glazing {ratio:.0%} of floor area {'≥' if ok else '<'} {params['min_ratio']:.0%}"))
    return out


@rule("ROOM-HAS-DOOR")
def room_has_door(model: Model, params: dict, spec: dict) -> list[Result]:
    exempt = set(params.get("exempt", ()))
    out = []
    for s in model.spaces:
        if s.category in exempt:
            continue
        has = any(s in model.spaces_touching(d) for d in model.doors_on(s.storey))
        out.append(_res(spec, s, None, None, has, f"{s.label}: {'has a door' if has else 'no door found'}"))
    return out


@rule("ROOM-CLEAR-HEIGHT")
def room_clear_height(model: Model, params: dict, spec: dict) -> list[Result]:
    """BayBO Art. 45 (1): habitable rooms need 2.40 m clear.

    Attic rooms are allowed 2.20 m over half their area; we have no roof geometry,
    so an attic room is measured against the attic limit and the approximation is
    stated in the message rather than hidden.
    """
    lim, attic = params["min_m"], params.get("attic_min_m", params["min_m"])
    applies = set(params.get("applies_to", HABITABLE))
    out = []
    for s in model.spaces:
        if s.category not in applies:
            continue
        limit = attic if s.storey.lower().startswith(("dach", "attic", "ober")) else lim
        h = s.height
        if not h:
            continue                      # no height in the model: nothing to assert
        ok = h + 1e-6 >= limit
        out.append(_res(spec, s, h, limit, ok,
                        f"{s.label}: clear height {h:.2f} m {'≥' if ok else '<'} {limit} m"))
    return out


@rule("DWELLING-FACILITIES")
def dwelling_facilities(model: Model, params: dict, spec: dict) -> list[Result]:
    """BayBO Art. 46 (1-2): a dwelling needs a kitchen and a bathroom.

    Checked per storey, which is the dwelling unit in the v1 single-storey model.
    """
    needs = list(params.get("needs", ("kitchen", "bathroom")))
    present = {s.category for s in model.spaces}
    out = []
    for want in needs:
        ok = want in present
        anchor = next(iter(model.spaces), None)
        if anchor is None:
            continue
        out.append(_res(spec, anchor, None, None, ok,
                        f"dwelling {'has' if ok else 'is MISSING'} a {want}"))
    return out


@rule("CORRIDOR-WIDTH")
def corridor_width(model: Model, params: dict, spec: dict) -> list[Result]:
    """DIN 18040-2 clear corridor width. Only meaningful once triggered."""
    lim = params["min_width"]
    out = []
    for s in model.spaces:
        if s.category != "hall":
            continue
        width, _ = _rect_dims(s.footprint)
        ok = width + 1e-6 >= lim
        out.append(_res(spec, s, width, lim, ok,
                        f"{s.label}: corridor width {width:.2f} m {'≥' if ok else '<'} {lim} m"))
    return out


@rule("MOVEMENT-AREA")
def movement_area(model: Model, params: dict, spec: dict) -> list[Result]:
    """DIN 18040-2 movement area, APPROXIMATED by the room's narrowest side.

    A true check needs furniture layout, which the model does not carry. The
    approximation is declared in the ruleset (`checkable: partial`) and repeated
    in every message, rather than presented as an exact result.
    """
    lim = params["min_side"]
    out = []
    for s in model.spaces:
        if s.category not in HABITABLE:
            continue
        width, _ = _rect_dims(s.footprint)
        ok = width + 1e-6 >= lim
        out.append(_res(spec, s, width, lim, ok,
                        f"{s.label}: narrowest side {width:.2f} m {'≥' if ok else '<'} {lim} m "
                        f"(approximation — no furniture layout in the model)"))
    return out


# --- running ---------------------------------------------------------------

def load_ruleset(path: str | Path | None = None) -> dict:
    return yaml.safe_load(Path(path or DEFAULT_RULESET).read_text(encoding="utf-8"))


def is_evaluable(spec: dict) -> bool:
    """Can this rule be decided from the model at all?

    Two kinds of rule legitimately have no geometric predicate:
      * `checkable: no`  -- the model carries no such data (smoke detectors,
        thresholds). Reported as NOT EVALUATED by recognition.score.
      * policy triggers (`when:`) -- these select other rulesets from the brief
        rather than judging geometry.
    Skipping them here is not hiding them: score.verdict() reports every one.
    """
    checkable = spec.get("checkable", True)
    if isinstance(checkable, bool):
        checkable = "yes" if checkable else "no"
    if str(checkable).lower() in ("no", "false"):
        return False
    return "when" not in spec


def check(model: Model, ruleset: dict | None = None) -> Report:
    ruleset = ruleset or load_ruleset()
    results: list[Result] = []
    for spec in ruleset["rules"]:
        if not is_evaluable(spec):
            continue
        fn = REGISTRY.get(spec["id"])
        if fn is None:
            raise KeyError(f"rule {spec['id']} declared in ruleset but not implemented")
        results.extend(fn(model, spec.get("params", {}), spec))
    return Report(ruleset["name"], str(ruleset.get("version", "")), model.path.name, results)


def to_markdown(report: Report) -> str:
    s = report.summary()
    status = "FAIL" if s["errors"] else ("WARN" if s["warnings"] else "PASS")
    out = [f"# Compliance report — {report.model}", "",
           f"**Status: {status}** — {s['checks']} checks, {s['passed']} passed, "
           f"{s['errors']} errors, {s['warnings']} warnings. Ruleset: {report.ruleset} v{report.version}", "",
           "| Rule | Severity | Checked | Failed |", "|---|---|---|---|"]
    out += [f"| {rid} — {d['title']} | {d['severity']} | {d['checked']} | {d['failed']} |" for rid, d in s["by_rule"].items()]
    if report.failures:
        out += ["", "## Findings", "", "| Rule | Sev | Element | Storey | Value | Limit | Message |", "|---|---|---|---|---|---|---|"]
        for r in report.failures:
            out.append(f"| {r.rule_id} | {r.severity} | {r.element_tag} | {r.storey} | "
                       f"{'' if r.value is None else r.value} | {'' if r.limit is None else r.limit} | {r.message} |")
    else:
        out += ["", "No findings."]
    return "\n".join(out) + "\n"


def write_report(report: Report, out_dir: Path) -> dict:
    out_dir = Path(out_dir)
    out_dir.mkdir(parents=True, exist_ok=True)
    data = {"ruleset": report.ruleset, "version": report.version, "model": report.model,
            "summary": report.summary(), "results": [asdict(r) for r in report.results]}
    (out_dir / "report.json").write_text(json.dumps(data, indent=2, ensure_ascii=False), encoding="utf-8")
    (out_dir / "report.md").write_text(to_markdown(report), encoding="utf-8")
    return data

