104	    });
105	    q.value = q.def;
106	    return wrap;
107	  }
108	
109	  if (q.type === "number") {
110	    const wrap = el("div", "pair");
111	    const i = el("input");
112	    Object.assign(i, { type: "number", id: `f-${q.id}`, value: q.def, min: q.min, max: q.max });
113	    i.oninput = () => { q.value = Number(i.value) || q.def; refreshAssumptions(); };
114	    q.value = q.def;
115	    wrap.append(i, el("span", null, q.unit || ""));
116	    return wrap;
117	  }
118	
119	  if (q.type === "rooms") {
120	    const grid = el("div", "rooms-grid");
121	    q.value = {};
122	    ROOMS.forEach((r) => {
123	      q.value[r.key] = r.def;
124	      const row = el("div", "room-row" + (r.def ? " on" : ""));
125	      const n = el("span", "n", String(r.def));
126	      const dec = el("button", null, "−"); dec.type = "button";
127	      const inc = el("button", null, "+"); inc.type = "button";
128	      const set = (v) => {
129	        q.value[r.key] = Math.max(0, Math.min(6, v));
130	        n.textContent = String(q.value[r.key]);
131	        row.classList.toggle("on", q.value[r.key] > 0);
132	        refreshAssumptions();
133	      };
134	      dec.onclick = () => set(q.value[r.key] - 1);
135	      inc.onclick = () => set(q.value[r.key] + 1);
136	      const step = el("div", "stepper");
137	      step.append(dec, n, inc);
138	      row.append(el("span", "nm", r.label), step);
139	      grid.append(row);
140	    });
141	    return grid;
142	  }
143	
144	  if (q.type === "plot") {
145	    const wrap = el("div", "pair");
146	    const w = el("input"), d = el("input");
147	    Object.assign(w, { type: "number", id: `f-${q.id}`, value: q.def[0], min: 5, max: 100 });
148	    Object.assign(d, { type: "number", value: q.def[1], min: 5, max: 100 });
149	    q.value = [...q.def];
150	    const upd = () => { q.value = [Number(w.value) || q.def[0], Number(d.value) || q.def[1]]; };
151	    w.oninput = upd; d.oninput = upd;
152	    wrap.append(w, el("span", null, "×"), d, el("span", null, "m"));
153	    return wrap;
154	  }
155	
156	  const i = el("input");
157	  Object.assign(i, { type: "text", id: `f-${q.id}`, placeholder: q.placeholder || "" });
158	  i.oninput = () => { q.value = i.value; };
159	  q.value = "";
160	  return i;
161	}
162	
163	/* Every value we infer is shown, with the reason. The silent default is the
164	   failure mode this whole product is designed against. */
165	function refreshAssumptions() {
166	  const dwellings = QUESTIONS.find((q) => q.id === "dwelling_count").value || 1;
167	  const chips = [
168	    ["ceiling height", "2.50 m", "BayBO Art. 45 (1) minimum 2.40 m + 100 mm build-up"],
169	    ["storeys", "1", "v1 designs a single storey"],
170	    ["glazing", "1/8 of floor area", "BayBO Art. 45 (2)"],
171	  ];
172	  if (dwellings > 2) {
173	    chips.push(["barrier-free", "DIN 18040-2", "BayBO Art. 48 (1): more than 2 homes"]);
174	  }
175	  const box = $("assumed-chips");
176	  box.innerHTML = "";
177	  chips.forEach(([k, v, basis]) => {
178	    const c = el("span", "chip");
179	    c.append(el("span", null, k + " "), el("b", null, v), el("span", "basis", "· " + basis));
180	    box.append(c);
181	  });
182	}
183	
184	function briefFromInterview() {
185	  const get = (id) => QUESTIONS.find((q) => q.id === id).value;
186	  const rooms = Object.entries(get("rooms"))
187	    .filter(([, n]) => n > 0)
188	    .map(([category, count]) => ({ category, count }));
189	  const [w, d] = get("plot");
190	  return {
191	    project: "Neubau",
192	    building_class: get("building_class"),
193	    dwelling_count: get("dwelling_count"),
194	    plot_width_m: w, plot_depth_m: d,
195	    rooms, notes: get("notes"),
196	    storey_count: 1, storey_height_m: 2.5, bundesland: "BY",
197	  };
198	}
199	
200	/* ══════════════════════════════════════════════════════════════════════
201	   2 · The 3D viewer
202	   ══════════════════════════════════════════════════════════════════════ */
203	
204	const COLOR = {
205	  bg: 0xffffff, wall: 0x9aa5ae, space: 0xdfe6ec,
206	  door: 0xd07a2a, window: 0x2a62d8, edge: 0x15191d,
207	  sky: 0xffffff, ground: 0xc7ced5,
208	};
209	const kindOf = (cls) =>
210	  cls === "IfcSpace" ? "space" : cls === "IfcDoor" ? "door" : cls === "IfcWindow" ? "window" : "wall";
211	
212	let V = null;
213	
214	function viewer() {
215	  if (V) return V;
216	  const host = $("v3-host");
217	  const renderer = new THREE.WebGLRenderer({ antialias: true, powerPreference: "high-performance" });
218	  renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
219	  renderer.domElement.className = "v3-canvas";
220	  host.append(renderer.domElement);
221	
222	  const scene = new THREE.Scene();
223	  scene.background = new THREE.Color(COLOR.bg);
224	  const camera = new THREE.PerspectiveCamera(38, 1, 0.05, 2000);
225	  const controls = new OrbitControls(camera, renderer.domElement);
226	  controls.enableDamping = true;
227	  controls.dampingFactor = 0.09;
228	
229	  scene.add(
230	    new THREE.HemisphereLight(COLOR.sky, COLOR.ground, 1.7),
231	    new THREE.AmbientLight(0xffffff, 0.35),
232	  );
233	  const sun = new THREE.DirectionalLight(0xffffff, 1.5);
234	  sun.position.set(1, 2, 1.4);
235	  scene.add(sun);
236	
237	  V = { renderer, scene, camera, controls, host, root: null,
238	        raycaster: new THREE.Raycaster(), pointer: new THREE.Vector2(), spaces: [] };
239	
240	  const resize = () => {
241	    const w = host.clientWidth || 1, h = host.clientHeight || 1;
242	    renderer.setSize(w, h, false);
243	    camera.aspect = w / h;
244	    camera.updateProjectionMatrix();
245	  };
246	  new ResizeObserver(resize).observe(host);
247	  resize();
248	
249	  host.addEventListener("pointermove", onHover);
250	  host.addEventListener("pointerleave", () => $("hoverchip").classList.add("hide"));
251	
252	  (function loop() {
253	    requestAnimationFrame(loop);
254	    controls.update();
255	    renderer.render(scene, camera);
256	  })();
257	  return V;
258	}
259	
260	function loadMesh(json) {
261	  const v = viewer();
262	  if (v.root) { v.scene.remove(v.root); disposeTree(v.root); }
263	  const root = new THREE.Group();
264	  v.spaces = [];
265	
266	  const [x0, y0, z0, x1, y1, z1] = json.bounds;
267	  const mid = new THREE.Vector3((x0 + x1) / 2, (y0 + y1) / 2, (z0 + z1) / 2);
268	
269	  for (const e of json.elements || []) {
270	    const kind = kindOf(e.cls);
271	    const g = new THREE.BufferGeometry();
272	    g.setAttribute("position", new THREE.Float32BufferAttribute(e.verts, 3));
273	    g.setIndex(e.faces);
274	    const flat = g.toNonIndexed();     // flat shading keeps corners crisp
275	    flat.computeVertexNormals();
276	    g.dispose();
277	    flat.translate(-mid.x, -mid.y, -mid.z);
278	
279	    const mat = new THREE.MeshLambertMaterial({
280	      color: COLOR[kind],
281	      transparent: kind === "space",
282	      opacity: kind === "space" ? 0.32 : 1,
283	      depthWrite: kind !== "space",
284	      side: kind === "space" ? THREE.DoubleSide : THREE.FrontSide,
285	    });
286	    const mesh = new THREE.Mesh(flat, mat);
287	    mesh.userData = { tag: e.tag, name: e.name, kind, area: e.area };
288	    if (kind === "space") v.spaces.push(mesh);
289	    root.add(mesh);
290	  }
291	
292	  // IFC is Z-up; three.js is Y-up.
293	  root.rotation.x = -Math.PI / 2;
294	  v.scene.add(root);
295	  v.root = root;
296	
297	  const span = Math.max(x1 - x0, y1 - y0, z1 - z0) || 10;
298	  v.camera.position.set(span * 0.95, span * 0.78, span * 1.05);
299	  v.controls.target.set(0, 0, 0);
300	  v.controls.update();
301	  applySpaceVisibility();
302	  $("v3-wait").classList.add("hide");
303	}
304	
305	function disposeTree(obj) {
306	  obj.traverse((o) => {
307	    if (o.geometry) o.geometry.dispose();
308	    if (o.material) o.material.dispose();
309	  });
310	}
311	
312	function applySpaceVisibility() {
313	  if (!V) return;
314	  const on = $("show-spaces").checked;
315	  V.spaces.forEach((m) => { m.visible = on; });
316	}
317	
318	function onHover(ev) {
319	  const v = viewer();
320	  if (!v.root) return;
321	  const r = v.host.getBoundingClientRect();
322	  v.pointer.set(((ev.clientX - r.left) / r.width) * 2 - 1, -((ev.clientY - r.top) / r.height) * 2 + 1);
323	  v.raycaster.setFromCamera(v.pointer, v.camera);
324	  const hit = v.raycaster.intersectObjects(v.root.children, false)
325	    .find((h) => h.object.visible && h.object.userData.kind === "space");
326	  const chip = $("hoverchip");
327	  if (!hit) { chip.classList.add("hide"); return; }
328	  const d = hit.object.userData;
329	  chip.textContent = `${d.tag ? d.tag + "  " : ""}${d.name}${d.area ? "  ·  " + d.area + " m²" : ""}`;
330	  chip.style.left = `${ev.clientX - r.left}px`;
331	  chip.style.top = `${ev.clientY - r.top}px`;
332	  chip.classList.remove("hide");
333	}
334	
335	/* ══════════════════════════════════════════════════════════════════════
336	   3 · Results
337	   ══════════════════════════════════════════════════════════════════════ */
338	
339	const base = (p, c) => `data/${p}/${c}`;
340	
341	async function openProject(key, candidate) {
342	  const run = await fetch(`data/${key}/run.json`).then((r) => r.json());
343	  State.run = run; State.project = key;
344	  State.candidate = candidate || run.winner || (run.candidates[0] || {}).name;
345	  show("result");
346	  $("doc-title").textContent = run.project;
347	  $("restart").classList.remove("hide");
348	  await showCandidate(State.candidate);
349	}
350	
351	async function showCandidate(name) {
352	  State.candidate = name;
353	  const p = State.project, dir = base(p, name);
354	
355	  const verdict = await fetch(`${dir}/verdict.json`).then((r) => r.json()).catch(() => null);
356	  renderStamp(verdict);
357	  renderFindings(verdict);
358	  renderRooms(verdict);
359	  renderOptions();
360	
361	  // Two very different failures used to report the same thing. "No model" when
362	  // the truth was "this browser has no WebGL" sends you looking in the wrong
363	  // place, so the fetch and the render are caught separately.
364	  const wait = $("v3-wait");
365	  wait.textContent = "loading model…";
366	  wait.classList.remove("hide");
367	  fetch(`${dir}/mesh.json`)
368	    .then((r) => (r.ok ? r.json() : Promise.reject(new Error(`mesh.json ${r.status}`))))
369	    .then((json) => {
370	      try {
371	        loadMesh(json);
372	      } catch (e) {
373	        wait.textContent = "3D needs WebGL, which this browser did not provide";
374	        wait.classList.remove("hide");
375	        console.error("3D render failed:", e);
376	      }
377	    })
378	    .catch(() => { wait.textContent = "no 3D model was published for this candidate"; });
379	
380	  fetch(`${dir}/sheet.svg`).then((r) => (r.ok ? r.text() : Promise.reject()))
381	    .then((svg) => { $("sheet-host").innerHTML = svg; })
382	    .catch(() => { $("sheet-host").innerHTML = '<p class="hint">no sheet for this candidate</p>'; });
383	  $("pdf-link").href = `${dir}/sheet.pdf`;
384	
385	  fetch(`${dir}/design.py`).then((r) => r.text())
386	    .then((src) => { $("tab-code").innerHTML = ""; $("tab-code").append(el("pre", "code", src)); })
387	    .catch(() => {});
388	}
389	
390	function renderStamp(v) {
391	  const host = $("top-stamp");
392	  host.classList.remove("hide");
393	  host.innerHTML = "";
394	  if (!v) return;
395	  const s = el("span", `stamp ${v.ok ? "pass" : "fail"}`);
396	  s.append(el("span", null, v.ok ? "PASS" : "FAIL"));
397	  // Never a bare PASS: what we could not check is part of the answer.
398	  s.append(el("span", "cov",
399	    `${v.checked} checked · ${v.not_evaluated} not evaluated · ${v.failed} failed`));
400	  host.append(s);
401	}
402	
403	const TIERS = [
404	  ["law", "Statute", "may block"],
405	  ["standard", "Standard", "blocks once triggered"],
406	  ["guidance", "Guidance", "advisory only"],
407	  ["house", "Practice", "advisory only"],
408	];
409	
410	function renderFindings(v) {
411	  const box = $("tab-findings");
412	  box.innerHTML = "";
413	  if (!v) { box.append(el("p", "hint", "No compliance result.")); return; }
414	
415	  const notable = (v.findings || []).filter((f) => f.status !== "passed");
416	  if (!notable.length) {
417	    box.append(el("p", "hint", "Every rule that could be evaluated passed."));
418	  }
419	  for (const [tier, label, note] of TIERS) {
420	    const items = notable.filter((f) => f.tier === tier);
421	    if (!items.length) continue;
422	    const g = el("div", "tier-group");
423	    const h = el("div", "tier-h");
424	    h.append(el("span", `tl ${tier}`, label), el("span", "tn", note));
425	    g.append(h);
426	    items.forEach((f) => {
427	      const d = el("div", `finding ${f.status}`);
428	      const r = el("div", "fr");
429	      r.append(el("span", "rid", f.rule_id));
430	      if (f.status === "not_evaluated") r.append(el("span", "hint", "not evaluated"));
431	      else if (f.blocking) r.append(el("span", "hint", "blocking"));
432	      d.append(r, el("div", "fm", f.message));
433	      const cite = el("div", "cite");
434	      if (f.url) {
435	        const a = el("a", null, f.citation);
436	        a.href = f.url; a.target = "_blank"; a.rel = "noopener";
437	        cite.append(a);
438	      } else cite.append(el("span", null, f.citation));
439	      d.append(cite);
440	      g.append(d);
441	    });
442	    box.append(g);
443	  }
444	}
445	
446	function renderRooms(v) {
447	  const box = $("tab-rooms");
448	  box.innerHTML = "";
449	  const m = (v && v.metrics) || {};
450	  const t = el("table", "rooms");
451	  t.innerHTML = "<thead><tr><th>Metric</th><th>Value</th></tr></thead>";
452	  const body = el("tbody");
453	  const rows = [
454	    ["Rooms", m.rooms], ["Envelope", m.envelope_m2 && m.envelope_m2 + " m²"],
455	    ["Room area", m.room_area_m2 && m.room_area_m2 + " m²"],
456	    ["Circulation", m.circulation_m2 && m.circulation_m2 + " m²"],
457	    ["Usable ratio", m.usable_ratio && (m.usable_ratio * 100).toFixed(1) + " %"],
458	    ["Doors + windows", m.openings],
459	  ];
460	  rows.forEach(([k, val]) => {
461	    if (val == null) return;
462	    const tr = el("tr");
463	    tr.append(el("td", null, k), el("td", "n", String(val)));
464	    body.append(tr);
465	  });
466	  t.append(body);
467	  box.append(t);
468	}
469	
470	function renderOptions() {
471	  const box = $("tab-options");
472	  box.innerHTML = "";
473	  const run = State.run;
474	  (run.candidates || []).forEach((c) => {
475	    const card = el("div", "opt-card" + (c.name === State.candidate ? " on" : ""));
476	    const h = el("div", "oh");
477	    h.append(el("span", "on-name", c.label || c.name));
478	    if (c.name === run.winner) h.append(el("span", "badge", "winner"));
479	    card.append(h);
480	    if (c.error) card.append(el("div", "od", c.error));
481	    const m = el("div", "om");
482	    m.append(el("span", null, `${c.checked} checked`),
483	             el("span", null, `${c.failed} failed`),
484	             el("span", null, `${c.not_evaluated} not evaluated`));
485	    card.append(m);
486	    card.onclick = () => showCandidate(c.name);
487	    box.append(card);
488	  });
489	  box.append(el("p", "chosen-note",
490	    "The winner was chosen by the scorer from the compliance result — not by a person and not by a model. Picking another here is a new view, not an approval."));
491	}
492	
493	/* ══════════════════════════════════════════════════════════════════════
494	   Shell
495	   ══════════════════════════════════════════════════════════════════════ */
496	
497	function show(which) {
498	  ["brief", "working", "result"].forEach((v) =>
499	    $(`view-${v}`).classList.toggle("hide", v !== which));
500	}
501	
502	function toast(msg, ms = 4200) {
503	  const t = $("toast");
504	  t.textContent = msg;
505	  t.classList.remove("hide");
506	  clearTimeout(toast._t);
507	  toast._t = setTimeout(() => t.classList.add("hide"), ms);
508	}
509	
510	const STEPS = [
511	  ["Brief sealed", "the last moment a person is involved"],
512	  ["Plan", "rooms, areas and adjacencies — no coordinates"],
513	  ["Translate", "plan → building code, zero model tokens"],
514	  ["Build", "IFC4, sheets, 3D mesh"],
515	  ["Verify", "every rule, with its citation"],
516	  ["Rank", "the scorer picks a winner"],
517	];
518	
519	function renderSteps(activeIdx) {
520	  const list = $("steps");
521	  list.innerHTML = "";
522	  STEPS.forEach(([lb, rt], i) => {
523	    const li = el("li", "step " + (i < activeIdx ? "done" : i === activeIdx ? "run" : "pend"));
524	    li.append(el("span", "dot"), el("span", "lb", lb), el("span", "rt", rt));
525	    list.append(li);
526	  });
527	}
528	
529	/* A static page cannot run the pipeline. Rather than fake it, the Studio says
530	   plainly what to run, hands over the brief, and shows what already exists. */
531	async function submitBrief(ev) {
532	  ev.preventDefault();
533	  State.brief = briefFromInterview();
534	  show("working");
535	  $("working-title").textContent = "Ready to run";
536	  let i = 0;
537	  renderSteps(0);
538	  const tick = setInterval(() => {
539	    i += 1;
540	    renderSteps(Math.min(i, 1));
541	    if (i >= 1) {
542	      clearInterval(tick);
543	      $("working-sub").textContent =
544	        "This page is static, so it cannot run the pipeline itself. Your brief is ready — run it, or open a design that already exists.";
545	      $("working-note").innerHTML =
546	        `uv run recognition autopilot &lt;your-brief.json&gt;`;
547	      const blob = new Blob([JSON.stringify(State.brief, null, 2)], { type: "application/json" });
548	      const a = el("a", "primary", "Download the brief");
549	      a.href = URL.createObjectURL(blob);
550	      a.download = "brief.json";
551	      a.style.display = "inline-block";
552	      a.style.textDecoration = "none";
553	      const back = el("button", "ghost", "Look at a finished design");
554	      back.type = "button";
555	      back.onclick = () => { show("brief"); document.getElementById("existing").scrollIntoView({ behavior: "smooth" }); };
556	      const row = el("div", "brief-actions");
557	      row.append(a, back);
558	      $("steps").after(row);
559	    }
560	  }, 420);
561	}
562	
563	async function boot() {
564	  renderInterview();
565	  $("interview").addEventListener("submit", submitBrief);
566	  $("show-spaces").addEventListener("change", applySpaceVisibility);
567	  $("restart").addEventListener("click", () => {
568	    show("brief");
569	    $("top-stamp").classList.add("hide");
570	    $("restart").classList.add("hide");
571	    $("doc-title").textContent = "A house, described";
572	  });
573	  document.querySelectorAll(".tabs button").forEach((b) => {
574	    b.onclick = () => {
575	      document.querySelectorAll(".tabs button").forEach((x) => x.classList.toggle("on", x === b));
576	      ["findings", "rooms", "options", "code"].forEach((t) =>
577	        $(`tab-${t}`).classList.toggle("hide", t !== b.dataset.tab));
578	    };
579	  });
580	
581	  let index = { projects: [] };
582	  try {
583	    index = await fetch("data/index.json").then((r) => r.json());
584	  } catch {
585	    $("existing").classList.add("hide");
586	  }
587	
588	  const grid = $("proj-grid");
589	  grid.innerHTML = "";
590	  if (!index.projects.length) $("existing").classList.add("hide");
591	  index.projects.forEach((p) => {
592	    const b = el("button", "proj");
593	    b.type = "button";
594	    b.append(el("div", "pn", p.project));
595	    b.append(el("div", "pm",
596	      `${p.candidates} layouts · ${p.checked} checked · ${p.not_evaluated} not evaluated · ${p.failed} failed`));
597	    b.onclick = () => openProject(p.key);
598	    grid.append(b);
599	  });
600	
601	  // Deep link: ?p=familienhaus&c=open
602	  const q = new URLSearchParams(location.search);
603	  if (q.get("p")) openProject(q.get("p"), q.get("c"));
604	}
605	
606	boot().catch((e) => toast("Could not start the Studio: " + e.message));
607

